  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Peso da Régua', 'Hlavní město portského vína na břehu Doura s muzeem vína a přístavištěm rabelos. Brána do vinařského údolí.', 41.1614, -7.7897, 'https://commons.wikimedia.org/wiki/Special:FilePath/Peso_da_R%C3%A9gua.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Peso_da_R%C3%A9gua.jpg"}'::text[], 0),
    (v_route, 'Pinhão', 'Srdce portské oblasti s nádražím zdobeným azulejos a vinicemi na strmých svazích. Nejfotogeničtější zastávka na Douru.', 41.1861, -7.5342, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pinh%C3%A3o.jpg"}'::text[], 1),
    (v_route, 'Vyhlídka São Leonardo de Galafura', 'Slavná vyhlídka vysoko nad zákrutem Doura s panoramatem teras a řeky. Nezapomenutelný rozhled nad údolím.', 41.1817, -7.6236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro_de_S%C3%A3o_Leonardo_de_Galafura.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro_de_S%C3%A3o_Leonardo_de_Galafura.jpg"}'::text[], 2),
    (v_route, 'Sabrosa', 'Rodiště mořeplavce Fernão de Magalhães uprostřed vinic. Klidné městečko s výhledy do kraje.', 41.2631, -7.5772, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sabrosa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sabrosa.jpg"}'::text[], 3),
    (v_route, 'Vinice Doura', 'Terasovité vinice na strmých svazích nad řekou, zapsané na seznam UNESCO. Ukázka portského terroir.', 41.1789, -7.55, 'https://commons.wikimedia.org/wiki/Special:FilePath/Douro_Valley.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Douro_Valley.jpg"}'::text[], 4);
