  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Torre – vrchol', 'Nejvyšší bod pevninského Portugalska (1993 m) s kamennou věží a výhledy do všech stran. Cíl slavného horského výjezdu.', 40.3225, -7.6153, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torre_Serra_da_Estrela.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torre_Serra_da_Estrela.jpg"}'::text[], 0),
    (v_route, 'Manteigas', 'Půvabné horské městečko v ledovcovém údolí Zêzere, výchozí bod do hor. Klidná zastávka mezi štíty.', 40.4008, -7.5344, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manteigas.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Manteigas.jpg"}'::text[], 1),
    (v_route, 'Ledovcové údolí Zêzere', 'Impozantní údolí ve tvaru U vyhloubené ledovcem, jedno z nejkrásnějších v Iberii. Dechberoucí scenérie za každého počasí.', 40.36, -7.56, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vale_do_Z%C3%AAzere.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vale_do_Z%C3%AAzere.jpg"}'::text[], 2),
    (v_route, 'Poço do Inferno', 'Malebný vodopád v lesích Serry da Estrela ukrytý v soutěsce. Osvěžující zastávka v přírodě.', 40.365, -7.51, 'https://commons.wikimedia.org/wiki/Special:FilePath/Po%C3%A7o_do_Inferno.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Po%C3%A7o_do_Inferno.jpg"}'::text[], 3),
    (v_route, 'Linhares da Beira', 'Historická vesnice s hradem na okraji pohoří, jedna z nejkrásnějších v zemi. Kamenné uličky a výhledy.', 40.5253, -7.4589, 'https://commons.wikimedia.org/wiki/Special:FilePath/Linhares_da_Beira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Linhares_da_Beira.jpg"}'::text[], 4);
