  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lázně Gerês', 'Termální lázeňské městečko v srdci národního parku, obklopené horami a lesy. Výchozí bod k vodopádům a přehradám.', 41.7256, -8.1594, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ger%C3%AAs.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ger%C3%AAs.jpg"}'::text[], 0),
    (v_route, 'Portela do Homem', 'Horský průsmyk na hranici se Španělskem s vodopády a starou římskou cestou. Nejvyšší bod okruhu s výhledy.', 41.8106, -8.12, 'https://commons.wikimedia.org/wiki/Special:FilePath/Portela_do_Homem.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Portela_do_Homem.jpg"}'::text[], 1),
    (v_route, 'Přehrada Vilarinho das Furnas', 'Nádrž ukrývající zatopenou vesnici, jejíž ruiny se za sucha vynoří. Působivé místo obklopené horami.', 41.7794, -8.2011, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vilarinho_das_Furnas.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vilarinho_das_Furnas.jpg"}'::text[], 2),
    (v_route, 'Soajo – sýpky', 'Vesnice proslulá skupinou kamenných obilných sýpek espigueiros na skále. Ojedinělá lidová památka severu.', 41.813, -8.2667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Soajo_espigueiros.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Soajo_espigueiros.jpg"}'::text[], 3),
    (v_route, 'Pedra Bela – vyhlídka', 'Vyhlídka nad údolím s panoramatem hor a přehrady Caniçada. Odměna za výjezd horskou silnicí.', 41.7658, -8.175, 'https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro_Pedra_Bela.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Miradouro_Pedra_Bela.jpg"}'::text[], 4);
