  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Palác Pena', 'Barevný romantický palác na vrcholu Sintry, jeden z divů Portugalska. Kýčovitě krásná stavba nad mlžnými lesy.', 38.7872, -9.3908, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pal%C3%A1cio_da_Pena.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pal%C3%A1cio_da_Pena.jpg"}'::text[], 0),
    (v_route, 'Historické centrum Sintry', 'Pohádkové městečko s národním palácem a kavárnami pod zalesněnými kopci. UNESCO klenot plný atmosféry.', 38.7975, -9.3903, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sintra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sintra.jpg"}'::text[], 1),
    (v_route, 'Cabo da Roca', 'Nejzápadnější bod kontinentální Evropy s majákem na útesech nad Atlantikem. Symbolický konec pevniny.', 38.7803, -9.4989, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_da_Roca.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_da_Roca.jpg"}'::text[], 2),
    (v_route, 'Quinta da Regaleira', 'Tajemná usedlost se zahradami, věžemi a hlubokou zasvěcovací studnou. Magické místo plné symboliky.', 38.7964, -9.3964, 'https://commons.wikimedia.org/wiki/Special:FilePath/Quinta_da_Regaleira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Quinta_da_Regaleira.jpg"}'::text[], 3),
    (v_route, 'Cascais', 'Elegantní přímořské letovisko s přístavem, plážemi a útesem Boca do Inferno. Příjemný cíl u moře.', 38.6975, -9.4211, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cascais.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cascais.jpg"}'::text[], 4);
