  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Évora – Dianin chrám', 'Historické město UNESCO s dochovaným římským chrámem, katedrálou a kaplí kostí. Srdce Alenteja plné památek.', 38.5714, -7.908, 'https://commons.wikimedia.org/wiki/Special:FilePath/Templo_romano_de_%C3%89vora.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Templo_romano_de_%C3%89vora.jpg"}'::text[], 0),
    (v_route, 'Monsaraz', 'Opevněné středověké městečko na kopci nad přehradou Alqueva s dechberoucím výhledem. Bílé uličky a hradby.', 38.4436, -7.3811, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monsaraz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monsaraz.jpg"}'::text[], 1),
    (v_route, 'Estremoz', 'Mramorové město s hradem, mramorovým náměstím a slavným keramickým trhem. Elegantní zastávka Alenteja.', 38.8442, -7.5864, 'https://commons.wikimedia.org/wiki/Special:FilePath/Estremoz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Estremoz.jpg"}'::text[], 2),
    (v_route, 'Přehrada Alqueva', 'Největší umělé jezero v západní Evropě, ráj temné oblohy a hvězd. Klidná vodní plocha uprostřed plání.', 38.3961, -7.4544, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barragem_do_Alqueva.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Barragem_do_Alqueva.jpg"}'::text[], 3),
    (v_route, 'Arraiolos', 'Kruhové městečko proslulé ručně vyšívanými koberci a hradem na kopci. Klidná zastávka mezi olivami.', 38.7239, -7.9836, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arraiolos.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arraiolos.jpg"}'::text[], 4);
