  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Fóia – nejvyšší vrchol Algarve', 'Nejvyšší bod Algarve (902 m) s výhledem přes hory až k Atlantiku. Cíl oblíbeného horského výjezdu.', 37.3147, -8.5992, 'https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%B3ia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%B3ia.jpg"}'::text[], 0),
    (v_route, 'Monchique', 'Horské městečko proslulé lázněmi, medovinou a řemesly, obklopené zelenými kopci. Svěží protipól pobřeží.', 37.3186, -8.5556, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monchique.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monchique.jpg"}'::text[], 1),
    (v_route, 'Hrad Silves', 'Mohutný červený maurský hrad nad bývalým hlavním městem Algarve. Nejlépe zachovaná maurská pevnost v regionu.', 37.1897, -8.4389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Silves.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Silves.jpg"}'::text[], 2),
    (v_route, 'Caldas de Monchique', 'Půvabná lázeňská osada ukrytá v eukalyptovém údolí s termálními prameny. Klidná zastávka mezi stromy.', 37.2894, -8.5581, 'https://commons.wikimedia.org/wiki/Special:FilePath/Caldas_de_Monchique.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Caldas_de_Monchique.jpg"}'::text[], 3),
    (v_route, 'Barragem da Bravura', 'Klidná přehrada v kopcích nad Lagosem obklopená borovicemi. Osvěžující zastávka daleko od davů.', 37.2158, -8.682, 'https://commons.wikimedia.org/wiki/Special:FilePath/Barragem_da_Bravura.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Barragem_da_Bravura.jpg"}'::text[], 4);
