  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Cabo de São Vicente', 'Dramatický mys na jihozápadním konci Evropy s majákem na útesech nad Atlantikem. Kdysi považován za konec světa.', 37.0209, -8.9964, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_de_S%C3%A3o_Vicente.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_de_S%C3%A3o_Vicente.jpg"}'::text[], 0),
    (v_route, 'Sagres', 'Větrné městečko s pevností na útesu, kolébka portugalských objevných plaveb. Surfařská a rybářská atmosféra.', 37.0119, -8.9411, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sagres.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sagres.jpg"}'::text[], 1),
    (v_route, 'Praia da Amoreira', 'Nádherná divoká pláž u ústí řeky s útesy a dunami. Ukázka syrové krásy Costa Vicentina.', 37.3242, -8.8811, 'https://commons.wikimedia.org/wiki/Special:FilePath/Praia_da_Amoreira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Praia_da_Amoreira.jpg"}'::text[], 2),
    (v_route, 'Aljezur', 'Bílé městečko s maurským hradem na kopci nedaleko divokých pláží. Klidná zastávka na severu pobřeží.', 37.3152, -8.7929, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aljezur.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aljezur.jpg"}'::text[], 3),
    (v_route, 'Odeceixe', 'Malebná vesnice nad meandrem řeky s plážou na hranici Alenteja a Algarve. Oblíbené místo surfařů.', 37.4335, -8.7645, 'https://commons.wikimedia.org/wiki/Special:FilePath/Odeceixe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Odeceixe.jpg"}'::text[], 4);
