  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Bragança', 'Výborně zachovaný středověký hrad s citadelou a domky uvnitř hradeb. Symbol nejsevernějšího portugalského kraje.', 41.8072, -6.7592, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Bragan%C3%A7a.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Bragan%C3%A7a.jpg"}'::text[], 0),
    (v_route, 'Miranda do Douro', 'Starobylé hraniční město nad kaňonem Doura, kde se dodnes mluví vlastním jazykem mirandštinou. Katedrála a dramatické útesy.', 41.4956, -6.2723, 'https://commons.wikimedia.org/wiki/Special:FilePath/Miranda_do_Douro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Miranda_do_Douro.jpg"}'::text[], 1),
    (v_route, 'Přírodní park Montesinho', 'Divoká horská krajina s vesnicemi, kde přežívají dávné tradice a vlci. Ryzí příroda severovýchodu.', 41.9302, -6.7965, 'https://commons.wikimedia.org/wiki/Special:FilePath/Parque_Natural_de_Montesinho.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Parque_Natural_de_Montesinho.jpg"}'::text[], 2),
    (v_route, 'Kaňon Doura – Douro Internacional', 'Hluboký kaňon, kterým řeka tvoří hranici se Španělskem, ráj dravců a divokých scenérií. Vyhlídky nad soutěskou.', 41.3675, -6.4258, 'https://commons.wikimedia.org/wiki/Special:FilePath/Douro_Internacional.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Douro_Internacional.jpg"}'::text[], 3),
    (v_route, 'Vila Real – Mateus', 'Město na úpatí hor s proslulým barokním palácem Mateus obklopeným zahradami. Elegantní zastávka na západě.', 41.308, -7.7378, 'https://commons.wikimedia.org/wiki/Special:FilePath/Casa_de_Mateus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Casa_de_Mateus.jpg"}'::text[], 4);
