  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Óbidos', 'Kouzelné městečko obepnuté středověkými hradbami s bílými domky a květinami. Jedna z nejhezčích vesnic Portugalska.', 39.3606, -9.1572, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%93bidos.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%93bidos.jpg"}'::text[], 0),
    (v_route, 'Templářský klášter v Tomaru', 'Convento de Cristo, sídlo templářů a UNESCO památka s proslulým oknem Manuelino. Klenot portugalské historie.', 39.6039, -8.4189, 'https://commons.wikimedia.org/wiki/Special:FilePath/Convento_de_Cristo_Tomar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Convento_de_Cristo_Tomar.jpg"}'::text[], 1),
    (v_route, 'Marvão', 'Orlí hnízdo na skalním vrcholu u španělské hranice s hradbami a nekonečnými výhledy do plání. Nezapomenutelná scenérie.', 39.3936, -7.3778, 'https://commons.wikimedia.org/wiki/Special:FilePath/Marv%C3%A3o.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Marv%C3%A3o.jpg"}'::text[], 2),
    (v_route, 'Castelo de Vide', 'Půvabné městečko s hradem a starou židovskou čtvrtí na svahu pod Marvãem. Kamenné uličky a prameny.', 39.4147, -7.4553, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Vide.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Vide.jpg"}'::text[], 3),
    (v_route, 'Almourol', 'Pohádkový templářský hrad na ostrůvku uprostřed řeky Tejo. Jeden z nejromantičtějších hradů Iberie.', 39.4614, -8.3814, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Almourol.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Almourol.jpg"}'::text[], 4);
