  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Univerzita Coimbra', 'Nejstarší univerzita Portugalska s ohromující barokní knihovnou Joanina, památka UNESCO. Srdce historického města nad řekou Mondego.', 40.2076, -8.4256, 'https://commons.wikimedia.org/wiki/Special:FilePath/University_of_Coimbra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/University_of_Coimbra.jpg"}'::text[], 0),
    (v_route, 'Hrad Lousã', 'Malebný hrad ukrytý v břidlicové soutěsce u říčky s pláží. Výchozí bod do hor obklopený zelení.', 40.0958, -8.2242, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Lous%C3%A3.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Lous%C3%A3.jpg"}'::text[], 1),
    (v_route, 'Talasnal', 'Kouzelná břidlicová vesnice zavěšená na svahu Serry da Lousã, kdysi opuštěná a znovu oživlá. Kamenné domky mimo čas.', 40.081, -8.238, 'https://commons.wikimedia.org/wiki/Special:FilePath/Talasnal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Talasnal.jpg"}'::text[], 2),
    (v_route, 'Penela – hrad', 'Dobře zachovalý hrad nad městečkem na okraji vápencových kopců. Rozhled do kraje a klidná zastávka.', 40.0322, -8.3903, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Penela.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castelo_de_Penela.jpg"}'::text[], 3),
    (v_route, 'Conímbriga', 'Nejlépe dochované římské ruiny v Portugalsku s mozaikami a lázněmi. Fascinující výlet do antiky.', 40.0994, -8.4919, 'https://commons.wikimedia.org/wiki/Special:FilePath/Con%C3%ADmbriga.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Con%C3%ADmbriga.jpg"}'::text[], 4);
